function verifyDeviceTypeExists(airflow, comments, custom_fields, default_platform, description, exclude_from_utilization, front_image, id, is_full_depth, manufacturer, model, part_number, rear_image, slug, subdevice_role, tags, u_height, weight, weight_unit) {
  var url = "/api/dcim/device-types/";
  bp.log.info("DEBUG VERIFIER for DeviceType: Arguments=" + JSON.stringify(arguments));
  var description = "[DeviceType] Verify DeviceType with id " + id + " exists";
  svc.get(url, { expectedResponseCodes: [200], callback: function(response) {
      var items = JSON.parse(response.body);
      if (items.results && Array.isArray(items.results)) { items = items.results; }
      if (!Array.isArray(items)) items = [items];
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          var match = false;
          if (String(items[i].id) === String(id)) match = true;
          if (match) return pvg.success("Entity exists");
        }
      }
      return pvg.fail("Expected DeviceType to exist but it does not");
    }
  });
}

