function verifyDeviceExists(airflow, asset_tag, cluster, comments, config_template, custom_fields, description, device_type, face, id, latitude, local_context_data, location, longitude, name, oob_ip, platform, position, primary_ip4, primary_ip6, rack, role, serial, site, status, tags, tenant, vc_position, vc_priority, virtual_chassis) {
  var url = "/api/dcim/devices/";
  bp.log.info("DEBUG VERIFIER for Device: Arguments=" + JSON.stringify(arguments));
  var description = "[Device] Verify Device with id " + id + " exists";
  svc.get(url, { expectedResponseCodes: [200], callback: function(response) {
      var items = JSON.parse(response.body);
      if (items.results && Array.isArray(items.results)) { items = items.results; }
      if (!Array.isArray(items)) items = [items];
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          var match = false;
          if (String(items[i].id) === String(id)) match = true;
          if (match) return pvg.success("Entity exists");
        }
      }
      return pvg.fail("Expected Device to exist but it does not");
    }
  });
}

