function verifyInventoryItemExists(asset_tag, component_id, component_type, custom_fields, description, device, discovered, id, label, manufacturer, name, parent, part_id, role, serial, status, tags) {
  var url = "/api/dcim/inventory-items/";
  bp.log.info("DEBUG VERIFIER for InventoryItem: Arguments=" + JSON.stringify(arguments));
  var description = "[InventoryItem] Verify InventoryItem with id " + id + " exists";
  svc.get(url, { expectedResponseCodes: [200], callback: function(response) {
      var items = JSON.parse(response.body);
      if (items.results && Array.isArray(items.results)) { items = items.results; }
      if (!Array.isArray(items)) items = [items];
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          var match = false;
          if (String(items[i].id) === String(id)) match = true;
          if (match) return pvg.success("Entity exists");
        }
      }
      return pvg.fail("Expected InventoryItem to exist but it does not");
    }
  });
}

