function verifyRackExists(airflow, asset_tag, comments, custom_fields, desc_units, description, facility_id, form_factor, id, location, manufacturer, max_weight, mounting_depth, name, outer_depth, outer_height, outer_unit, outer_width, rack_type, role, serial, site, starting_unit, status, tags, tenant, u_height, weight, weight_unit, width) {
  var url = "/api/dcim/racks/";
  bp.log.info("DEBUG VERIFIER for Rack: Arguments=" + JSON.stringify(arguments));
  var description = "[Rack] Verify Rack with id " + id + " exists";
  svc.get(url, { expectedResponseCodes: [200], callback: function(response) {
      var items = JSON.parse(response.body);
      if (items.results && Array.isArray(items.results)) { items = items.results; }
      if (!Array.isArray(items)) items = [items];
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          var match = false;
          if (String(items[i].id) === String(id)) match = true;
          if (match) return pvg.success("Entity exists");
        }
      }
      return pvg.fail("Expected Rack to exist but it does not");
    }
  });
}

function verifyRackDoesNotExist(airflow, asset_tag, comments, custom_fields, desc_units, description, facility_id, form_factor, id, location, manufacturer, max_weight, mounting_depth, name, outer_depth, outer_height, outer_unit, outer_width, rack_type, role, serial, site, starting_unit, status, tags, tenant, u_height, weight, weight_unit, width) {
  var url = "/api/dcim/racks/";
  var description = "[Rack] Verify Rack does not exist";
  svc.get(url, { expectedResponseCodes: [200], callback: function(response) {
      var items = JSON.parse(response.body);
      if (items.results && Array.isArray(items.results)) { items = items.results; }
      if (!Array.isArray(items)) items = [items];
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          var match = false;
          if (String(items[i].id) === String(id)) match = true;
          if (match) return pvg.fail("Expected Entity to not exist but it does");
        }
      }
      return pvg.success("Rack does not exist");
    }
  });
}

