function waitForAnyCustomFieldAdded() {
  var ev = waitFor(matchesDescriptionRegex(/^\[CustomField\]\ Create\ custom\ field\ (.*?)\ with\ id\ (.*?)$/));
  if (ev && ev.data && ev.data.parameters && ev.data.parameters.description) { bp.log.info("DEBUG MATCHER for CustomField: Matched event: " + ev.data.parameters.description); }
  var m = ev.data.parameters.description.match(/^\[CustomField\]\ Create\ custom\ field\ (.*?)\ with\ id\ (.*?)$/);
  var captures = m.slice(1);
  var names = ["name", "id"];
  var capturedMap = {};
  for (var i = 0; i < names.length; i++) { capturedMap[names[i]] = (i < captures.length) ? captures[i] : undefined; }
  var obj = {};
  obj["choice_set"] = capturedMap["choice_set"];
  obj["comments"] = capturedMap["comments"];
  obj["default"] = capturedMap["default"];
  obj["description"] = capturedMap["description"];
  obj["filter_logic"] = capturedMap["filter_logic"];
  obj["group_name"] = capturedMap["group_name"];
  obj["id"] = capturedMap["id"];
  obj["is_cloneable"] = capturedMap["is_cloneable"];
  obj["label"] = capturedMap["label"];
  obj["name"] = capturedMap["name"];
  obj["object_type"] = capturedMap["object_type"];
  obj["object_types"] = capturedMap["object_types"];
  obj["related_object_filter"] = capturedMap["related_object_filter"];
  obj["related_object_type"] = capturedMap["related_object_type"];
  obj["required"] = capturedMap["required"];
  obj["search_weight"] = capturedMap["search_weight"];
  obj["type"] = capturedMap["type"];
  obj["ui_editable"] = capturedMap["ui_editable"];
  obj["ui_visible"] = capturedMap["ui_visible"];
  obj["unique"] = capturedMap["unique"];
  obj["validation_maximum"] = capturedMap["validation_maximum"];
  obj["validation_minimum"] = capturedMap["validation_minimum"];
  obj["validation_regex"] = capturedMap["validation_regex"];
  obj["weight"] = capturedMap["weight"];
  return obj;
}

function matchAnyCustomFieldAdded() { return bp.EventSet("matchAnyCustomFieldAdded", function(e) { return e.name.startsWith("Done: ") && e.name.indexOf("[CustomField]") > -1; }); }
function waitForCustomFieldAdded(choice_set, comments, _default, description, filter_logic, group_name, id, is_cloneable, label, name, object_type, object_types, related_object_filter, related_object_type, required, search_weight, type, ui_editable, ui_visible, unique, validation_maximum, validation_minimum, validation_regex, weight) { var expectedDesc = "[CustomField] Create custom field " + name + " with id " + id; waitFor(matchSuccess(expectedDesc)); }

