function waitForAnySavedFilterAdded() {
  var ev = waitFor(matchesDescriptionRegex(/^\[SavedFilter\]\ Create\ saved\ filter\ with\ name\ (.*?)\ with\ id\ (.*?)$/));
  if (ev && ev.data && ev.data.parameters && ev.data.parameters.description) { bp.log.info("DEBUG MATCHER for SavedFilter: Matched event: " + ev.data.parameters.description); }
  var m = ev.data.parameters.description.match(/^\[SavedFilter\]\ Create\ saved\ filter\ with\ name\ (.*?)\ with\ id\ (.*?)$/);
  var captures = m.slice(1);
  var names = ["name", "id"];
  var capturedMap = {};
  for (var i = 0; i < names.length; i++) { capturedMap[names[i]] = (i < captures.length) ? captures[i] : undefined; }
  var obj = {};
  obj["description"] = capturedMap["description"];
  obj["enabled"] = capturedMap["enabled"];
  obj["filters"] = capturedMap["filters"];
  obj["id"] = capturedMap["id"];
  obj["name"] = capturedMap["name"];
  obj["object_type"] = capturedMap["object_type"];
  obj["object_types"] = capturedMap["object_types"];
  obj["parameters"] = capturedMap["parameters"];
  obj["shared"] = capturedMap["shared"];
  obj["slug"] = capturedMap["slug"];
  obj["user"] = capturedMap["user"];
  obj["weight"] = capturedMap["weight"];
  return obj;
}

