function verifyContactAssignmentExists(contact, custom_fields, id, object_id, object_type, priority, role, tags) {
  var url = "/api/tenancy/contact-assignments/";
  bp.log.info("DEBUG VERIFIER for ContactAssignment: Arguments=" + JSON.stringify(arguments));
  var description = "[ContactAssignment] Verify ContactAssignment with id " + id + " exists";
  svc.get(url, { expectedResponseCodes: [200], callback: function(response) {
      var items = JSON.parse(response.body);
      if (items.results && Array.isArray(items.results)) { items = items.results; }
      if (!Array.isArray(items)) items = [items];
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          var match = false;
          if (String(items[i].id) === String(id)) match = true;
          if (match) return pvg.success("Entity exists");
        }
      }
      return pvg.fail("Expected ContactAssignment to exist but it does not");
    }
  });
}

