function verifyTenantExists(comments, contact, contact_group, contact_role, custom_fields, description, group, id, name, slug, tags) {
  var url = "/api/tenancy/tenants/";
  bp.log.info("DEBUG VERIFIER for Tenant: Arguments=" + JSON.stringify(arguments));
  var description = "[Tenant] Verify Tenant with id " + id + " exists";
  svc.get(url, { expectedResponseCodes: [200], callback: function(response) {
      var items = JSON.parse(response.body);
      if (items.results && Array.isArray(items.results)) { items = items.results; }
      if (!Array.isArray(items)) items = [items];
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          var match = false;
          if (String(items[i].id) === String(id)) match = true;
          if (match) return pvg.success("Entity exists");
        }
      }
      return pvg.fail("Expected Tenant to exist but it does not");
    }
  });
}

